    /// @param triggerLtv The configured trigger LTV.
    /// @param lltv The market's liquidation LTV.
    /// @param maxTriggerLtv The maximum allowed trigger LTV (derived from `lltv * MAX_TRIGGER_LTV_RATIO`).
    error TriggerLtvTooCloseToLltv(uint256 triggerLtv, uint256 lltv, uint256 maxTriggerLtv);

    /// @notice Thrown when the position's LTV remains at or above the market's LLTV after the top-up.
    ///
    /// @param postTopUpLtv The position's LTV after the top-up (WAD-scaled).
    /// @param lltv The market's liquidation LTV.
    error PostTopUpLtvAboveLltv(uint256 postTopUpLtv, uint256 lltv);

    /// @notice Thrown when `maxTriggerLtvRatio` is out of valid range (must be 0 < ratio < 1e18).
    ///
    /// @param ratio The invalid ratio that was provided.
    error InvalidMaxTriggerLtvRatio(uint256 ratio);

    /// @notice Thrown when an account attempts to install multiple active policies for the same marketId.
    error PolicyAlreadyInstalledForMarket(address account, Id marketId);

    ////////////////////////////////////////////////////////////////
    ///                       Constructor                        ///
    ////////////////////////////////////////////////////////////////

    /// @notice Constructs the policy.
    ///
    /// @param policyManager Address of the `PolicyManager` authorized to call hooks.
    /// @param admin Address that receives `DEFAULT_ADMIN_ROLE` and `PAUSER_ROLE`.
    /// @param morpho_ Morpho Blue singleton contract address.
    /// @param maxTriggerLtvRatio_ Maximum allowed ratio of `triggerLtv` to the market's `lltv` (WAD-scaled).
    ///        Must satisfy 0 < ratio < 1e18. For example, 0.95e18 means `triggerLtv` must be below 95% of
    ///        `lltv`.
    constructor(address policyManager, address admin, address morpho_, uint256 maxTriggerLtvRatio_)
        SingleExecutorAuthorizedPolicy(policyManager, admin)
    {
        if (_isNotPersistentCode(morpho_)) revert MorphoNotContract(morpho_);
        if (maxTriggerLtvRatio_ == 0 || maxTriggerLtvRatio_ >= 1e18) {
            revert InvalidMaxTriggerLtvRatio(maxTriggerLtvRatio_);
        }
        MORPHO = morpho_;
        MAX_TRIGGER_LTV_RATIO = maxTriggerLtvRatio_;
    }

    ////////////////////////////////////////////////////////////////
    ///                 External View Functions                  ///
    ////////////////////////////////////////////////////////////////

    /// @notice Convenience alias for `MORPHO` (lowercase getter).
    function morpho() external view returns (address) {
        return MORPHO;
    }

    /// @notice Return whether the policyId has been used (one-shot).
    ///
    /// @param policyId Policy identifier to check.
    ///
    /// @return True if the policy has already executed its one-shot top-up.
    function isPolicyUsed(bytes32 policyId) external view returns (bool) {
        return _usedPolicyId[policyId];
    }

    ////////////////////////////////////////////////////////////////
    ///                    Internal Functions                    ///
    ////////////////////////////////////////////////////////////////

    /// @inheritdoc SingleExecutorAuthorizedPolicy
    ///
    /// @dev Validates config, enforces one-policy-per-market, and stores market linkage for uninstall.
    function _onSingleExecutorInstall(
        bytes32 policyId,
        address account,
        SingleExecutorConfig memory,
        bytes memory policySpecificConfig
    ) internal virtual override {
        LoanProtectionPolicyConfig memory config = abi.decode(policySpecificConfig, (LoanProtectionPolicyConfig));
        bytes32 marketKey = Id.unwrap(config.marketId);
        if (marketKey == bytes32(0)) revert ZeroMarketId();
        if (config.maxTopUpAssets == 0) revert ZeroAmount();

        // Ensure the pinned market exists on this Morpho instance.
        MarketParams memory marketParams = _requireMarketParams(config.marketId);

        // Reject a zero trigger LTV (uint256 comparison `currentLtv < 0` is always false, so zero
        // would allow unconditional execution regardless of position health).
        if (config.triggerLtv == 0) revert ZeroTriggerLtv();

        // Ensure the trigger LTV is below a proportional ceiling of the market's liquidation LTV
        // so the executor has a meaningful reaction window before the position becomes liquidatable.
        // e.g., MAX_TRIGGER_LTV_RATIO = 0.95e18 → triggerLtv must be < 95% of lltv.
        // The `triggerLtv >= lltv` branch is defense-in-depth: when the constructor enforces
        // `0 < ratio < 1e18`, `maxTriggerLtv < lltv` always holds, but we guard against
        // misconfiguration weakening the buffer guarantee.
        uint256 maxTriggerLtv = Math.mulDiv(marketParams.lltv, MAX_TRIGGER_LTV_RATIO, 1e18);
        if (config.triggerLtv >= maxTriggerLtv || config.triggerLtv >= marketParams.lltv) {
            revert TriggerLtvTooCloseToLltv(config.triggerLtv, marketParams.lltv, maxTriggerLtv);
        }

        // Ensure only one active policy per (account, market).
        if (activePolicyByMarket[account][marketKey] != bytes32(0)) {
            revert PolicyAlreadyInstalledForMarket(account, config.marketId);
        }
        activePolicyByMarket[account][marketKey] = policyId;
        marketKeyByPolicyId[policyId] = marketKey;
    }

    /// @inheritdoc SingleExecutorAuthorizedPolicy
    ///
    /// @dev Clears per-install state for a policy instance.
    function _onSingleExecutorUninstall(bytes32 policyId, address account, address) internal override {
        _clearInstallState(policyId, account);
    }

    /// @dev Clears per-install state mappings (`activePolicyByMarket`, `marketKeyByPolicyId`).
    ///      Safe to call even if state was already cleared or never set.
    ///
    /// @param policyId Policy identifier whose state should be cleared.
    /// @param account  Account associated with the policy instance.
    function _clearInstallState(bytes32 policyId, address account) internal {
        bytes32 marketKey = marketKeyByPolicyId[policyId];
        if (marketKey != bytes32(0)) {
            delete activePolicyByMarket[account][marketKey];
            delete marketKeyByPolicyId[policyId];
        }
    }

    /// @inheritdoc SingleExecutorAuthorizedPolicy
    ///
    /// @dev Executes a collateral top-up once, enforcing trigger LTV and one-shot semantics.
    function _onSingleExecutorExecute(
        bytes32 policyId,
        address account,
        SingleExecutorConfig memory,
        bytes memory policySpecificConfig,
        bytes memory actionData
    ) internal virtual override returns (bytes memory accountCallData, bytes memory postCallData) {
        // One-shot guard: revert if already used, otherwise mark consumed.
        if (_usedPolicyId[policyId]) revert PolicyAlreadyUsed(policyId);
        _usedPolicyId[policyId] = true;

        // Decode config and resolve on-chain market params (reverts if market is uninitialized).
        LoanProtectionPolicyConfig memory config = abi.decode(policySpecificConfig, (LoanProtectionPolicyConfig));
        MarketParams memory marketParams = _requireMarketParams(config.marketId);

        // Validate top-up amount and enforce LTV trigger.
        uint256 topUpAssets;
        {
            TopUpData memory topUp = abi.decode(actionData, (TopUpData));
            topUpAssets = topUp.topUpAssets;
            if (topUpAssets == 0) revert ZeroAmount();
            if (topUpAssets > config.maxTopUpAssets) revert TopUpAboveMax(topUpAssets, config.maxTopUpAssets);

            uint256 currentLtv = _computeCurrentLtv(config, marketParams, account);
            if (currentLtv < config.triggerLtv) revert HealthyPosition(currentLtv, config.triggerLtv);
        }

        // Build wallet call plan: zero-approve (for non-standard tokens like USDT), approve, then supply collateral.
        CoinbaseSmartWallet.Call[] memory calls = new CoinbaseSmartWallet.Call[](3);
        calls[0] = CoinbaseSmartWallet.Call({
            target: marketParams.collateralToken,
            value: 0,
            data: abi.encodeWithSelector(IERC20.approve.selector, MORPHO, 0)
        });
        calls[1] = CoinbaseSmartWallet.Call({
            target: marketParams.collateralToken,
            value: 0,
            data: abi.encodeWithSelector(IERC20.approve.selector, MORPHO, topUpAssets)
        });
        calls[2] = CoinbaseSmartWallet.Call({
            target: MORPHO,
            value: 0,
            data: abi.encodeWithSelector(
                IMorphoBlue.supplyCollateral.selector, marketParams, topUpAssets, account, bytes("")
            )
        });

        accountCallData = abi.encodeWithSelector(CoinbaseSmartWallet.executeBatch.selector, calls);
        postCallData = abi.encode(config, marketParams);
    }

    /// @dev Verifies that the position's LTV is below the market's LLTV after the top-up. If the
    ///      top-up was insufficient to bring the position out of the liquidation zone (e.g., due to
    ///      price movement between the executor's signature and transaction inclusion), the entire
    ///      transaction reverts — preserving the one-shot and the account's collateral.
    function _onPostExecute(bytes32, address account, bytes calldata postCallData) internal override {
        (LoanProtectionPolicyConfig memory config, MarketParams memory marketParams) =
            abi.decode(postCallData, (LoanProtectionPolicyConfig, MarketParams));

        uint256 postTopUpLtv = _computeCurrentLtv(config, marketParams, account);
        if (postTopUpLtv >= marketParams.lltv) revert PostTopUpLtvAboveLltv(postTopUpLtv, marketParams.lltv);
    }

    /// @notice Looks up market params from `marketId` and reverts if the market is not initialized.
    ///
    /// @param marketId_ Market identifier.
    ///
    /// @return marketParams Market parameters for the given marketId.
    function _requireMarketParams(Id marketId_) internal view returns (MarketParams memory marketParams) {
        marketParams = IMorphoBlue(MORPHO).idToMarketParams(marketId_);
        // Treat zeroed params as "market does not exist / not initialized on this Morpho instance".
        if (
            marketParams.loanToken == address(0) || marketParams.collateralToken == address(0)
                || marketParams.oracle == address(0) || marketParams.irm == address(0) || marketParams.lltv == 0
        ) revert MarketNotFound(marketId_);

        // Morpho sets lastUpdate = block.timestamp on createMarket; a zero value means the market
        // was never created via the canonical path.
        Market memory mkt = IMorphoBlue(MORPHO).market(marketId_);
        if (mkt.lastUpdate == 0) revert MarketNotFound(marketId_);
    }

    /// @dev Computes the account's current LTV as a WAD-scaled value (1e18 = 100%) using the Morpho Blue
    ///      position, market totals, and oracle price. Calls `accrueInterest` first to ensure
    ///      `totalBorrowAssets` and `totalBorrowShares` reflect accrued interest. Converts borrow shares
    ///      to debt assets using Morpho's virtual shares/assets offset and rounds up (worst-case debt).
    ///      Reverts with `ZeroCollateralValue` if the collateral position has zero value after oracle
    ///      pricing (which would cause a division-by-zero in the LTV calculation).
    ///
    /// @param config       Policy config containing the market identifier.
    /// @param marketParams On-chain market parameters (used to locate the oracle and collateral token).
    /// @param account      Account whose position is evaluated.
    ///
    /// @return currentLtvWad Current LTV in WAD (1e18 = 100%).
    function _computeCurrentLtv(
        LoanProtectionPolicyConfig memory config,
        MarketParams memory marketParams,
        address account
    ) internal returns (uint256 currentLtvWad) {
        IMorphoBlue morphoBlue = IMorphoBlue(MORPHO);

        // Accrue interest so totalBorrowAssets/totalBorrowShares are up to date.
        morphoBlue.accrueInterest(marketParams);

        Position memory position = morphoBlue.position(config.marketId, account);
        Market memory market = morphoBlue.market(config.marketId);

        uint256 collateralBefore = uint256(position.collateral);

        uint256 debtAssets = SharesMathLib.toAssetsUp(
            uint256(position.borrowShares), uint256(market.totalBorrowAssets), uint256(market.totalBorrowShares)
        );

        uint256 price = IOracle(marketParams.oracle).price(); // 1e36 scaled

        uint256 collateralValueBefore = Math.mulDiv(collateralBefore, price, 1e36);
        if (collateralValueBefore == 0) revert ZeroCollateralValue();

        currentLtvWad = Math.mulDiv(debtAssets, 1e18, collateralValueBefore);
    }

    /// @dev Returns the EIP-712 domain name and version used for executor signature verification.
    ///
    /// @return name    Domain name (`"Morpho Loan Protection Policy"`).
    /// @return version Domain version (`"1"`).
    function _domainNameAndVersion()
        internal
        pure
        virtual
        override
        returns (string memory name, string memory version)
    {
        name = "Morpho Loan Protection Policy";
        version = "1";
    }
}


